//! The desktop recovery key (Q-210, U-23), typed ahead of the engine merge
//! (capability `recovery-key-v1`).
//!
//! - The key is generated by the engine at first-run setup (returned once
//!   by `POST /api/v1/desktop/initialize`, see `cl-host`) and stored only
//!   as a hash.
//! - `POST /api/v1/desktop/recover-password {email, recoveryKey,
//!   newPassword}` resets the owner password; launch-token gated and
//!   rate-limited, no session needed.
//! - `POST /api/v1/auth/recovery-key/rotate` returns a fresh key once.
//!
//! Keys and passwords are [`Secret`]s: never logged, never in `Debug`.

use cl_core::Secret;
use serde::Deserialize;
use serde::ser::SerializeStruct;
use serde::{Serialize, Serializer};

use crate::client::{AttemptAuth, Call, Method, TimeoutClass};
use crate::errors::{ApiError, LocalValidation};
use crate::idempotency::StaticAuth;
use crate::resources::operations::{RECOVER_PASSWORD, RECOVERY_KEY_ROTATE};
use crate::session::{Client, Session, decode, json_body};

/// Input of [`Client::recover_password`].
#[derive(Clone)]
pub struct PasswordRecovery {
    /// The owner's sign-in email.
    pub email: String,
    /// The recovery key shown at setup.
    pub recovery_key: Secret,
    /// The new password (12+ characters, Q-211).
    pub new_password: Secret,
}

impl std::fmt::Debug for PasswordRecovery {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("PasswordRecovery").finish_non_exhaustive()
    }
}

impl Serialize for PasswordRecovery {
    fn serialize<S: Serializer>(&self, s: S) -> Result<S::Ok, S::Error> {
        let mut st = s.serialize_struct("PasswordRecovery", 3)?;
        st.serialize_field("email", &self.email)?;
        st.serialize_field("recoveryKey", self.recovery_key.expose())?;
        st.serialize_field("newPassword", self.new_password.expose())?;
        st.end()
    }
}

/// Minimum password length (Q-211).
pub const PASSWORD_MIN_CHARS: usize = 12;

/// Normalises a key the owner typed: trims, uppercases, and drops spaces
/// and hyphens, so `abcd-efgh` and `ABCD EFGH` compare equal.
#[must_use]
pub fn normalize_recovery_key(typed: &str) -> Secret {
    Secret::new(
        typed
            .chars()
            .filter(char::is_ascii_alphanumeric)
            .map(|c| c.to_ascii_uppercase())
            .collect::<String>(),
    )
}

impl Client {
    /// `POST /api/v1/desktop/recover-password`. Never retried.
    ///
    /// # Errors
    /// `Local(InvalidValue)` for an empty key or a short password (nothing
    /// sent); `Unauthorized(InvalidCredentials)` for a wrong key;
    /// `RateLimited`; `NotFound` on an engine without U-23; any
    /// [`ApiError`].
    pub async fn recover_password(&self, recovery: &PasswordRecovery) -> Result<(), ApiError> {
        if recovery.recovery_key.is_empty()
            || recovery.new_password.expose().chars().count() < PASSWORD_MIN_CHARS
            || recovery.email.trim().is_empty()
        {
            return Err(ApiError::Local(LocalValidation::InvalidValue));
        }
        let call = Call::at(Method::Post, RECOVER_PASSWORD.route())
            .json_body(json_body(recovery)?)
            .timeout(TimeoutClass::Auth);
        self.exec()
            .run(
                &RECOVER_PASSWORD,
                call,
                &StaticAuth(AttemptAuth::default()),
                None,
            )
            .await
            .map(drop)
    }
}

impl Session {
    /// `POST /api/v1/auth/recovery-key/rotate`: a new recovery key, shown
    /// once; the old one stops working. Never retried.
    ///
    /// # Errors
    /// `Forbidden` for a non-admin; `NotFound` on an engine without U-23;
    /// any [`ApiError`].
    pub async fn rotate_recovery_key(&self) -> Result<Secret, ApiError> {
        #[derive(Deserialize)]
        #[serde(rename_all = "camelCase")]
        struct W {
            recovery_key: String,
        }
        let call = Call::at(Method::Post, RECOVERY_KEY_ROTATE.route()).timeout(TimeoutClass::Auth);
        let reply = self.send(&RECOVERY_KEY_ROTATE, call, None).await?;
        Ok(Secret::new(
            decode::<W>(&reply, "recovery key")?.recovery_key,
        ))
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::resources::testkit::{company_session, json, requests};
    use serde_json::Value;
    use wiremock::matchers::{method, path};
    use wiremock::{Mock, MockServer};

    #[tokio::test]
    async fn recover_sends_the_key_once_and_hides_it_in_debug() {
        let server = MockServer::start().await;
        Mock::given(method("POST"))
            .and(path("/api/v1/desktop/recover-password"))
            .respond_with(json(
                401,
                r#"{"error":{"message":"bad","code":"INVALID_CREDENTIALS"}}"#,
            ))
            .mount(&server)
            .await;
        let s = company_session(&server);
        let r = PasswordRecovery {
            email: "owner@example.com".into(),
            recovery_key: normalize_recovery_key("abcd-efgh 1234"),
            new_password: Secret::new("a-new-password-123"),
        };
        assert_eq!(r.recovery_key.expose(), "ABCDEFGH1234");
        assert!(!format!("{r:?}").contains("ABCDEFGH"));
        let e = s
            .client()
            .recover_password(&r)
            .await
            .expect_err("wrong key");
        assert!(matches!(
            e,
            ApiError::Unauthorized(crate::AuthFailure::InvalidCredentials)
        ));
        let posts = requests(&server, "POST").await;
        assert_eq!(posts.len(), 1, "never retried");
        let body: Value = serde_json::from_slice(&posts[0].body).expect("json");
        assert_eq!(body["recoveryKey"], "ABCDEFGH1234");
        assert!(posts[0].headers.get("authorization").is_none());

        let short = PasswordRecovery {
            new_password: Secret::new("short"),
            ..r
        };
        let e = s
            .client()
            .recover_password(&short)
            .await
            .expect_err("short");
        assert_eq!(e, ApiError::Local(LocalValidation::InvalidValue));
        assert_eq!(requests(&server, "POST").await.len(), 1);
    }

    #[tokio::test]
    async fn rotate_returns_a_secret() {
        let server = MockServer::start().await;
        Mock::given(method("POST"))
            .and(path("/api/v1/auth/recovery-key/rotate"))
            .respond_with(json(200, r#"{"recoveryKey":"NEWKEY-CANARY"}"#))
            .mount(&server)
            .await;
        let key = company_session(&server)
            .rotate_recovery_key()
            .await
            .expect("key");
        assert_eq!(key.expose(), "NEWKEY-CANARY");
        assert!(!format!("{key:?}").contains("CANARY"));
    }
}
